   672  /* Creates an empty PFX structure for the PKCS12 structure.
   673   */
   674  static int create_empty_pfx(ASN1_TYPE pkcs12)
   675  {
   676          uint8_t three = 3;
   677          int result;
   678          ASN1_TYPE c2 = ASN1_TYPE_EMPTY;
   679
   680          /* Use version 3
   681           */
   682          result = asn1_write_value(pkcs12, "version", &three, 1);
   683          if (result != ASN1_SUCCESS) {
   684                  gnutls_assert();
   685                  result = _gnutls_asn2err(result);
   686                  goto cleanup;
   687          }
   688
   689          /* Write the content type of the data
   690           */
   691          result =
   692              asn1_write_value(pkcs12, "authSafe.contentType", DATA_OID, 1);
   693          if (result != ASN1_SUCCESS) {
   694                  gnutls_assert();
   695                  result = _gnutls_asn2err(result);
   696                  goto cleanup;
   697          }
   698
   699          /* Check if the authenticatedSafe content is empty, and encode a
   700           * null one in that case.
   701           */
   702
   703          if ((result = asn1_create_element
   704               (_gnutls_get_pkix(), "PKIX1.pkcs-12-AuthenticatedSafe",
   705                &c2)) != ASN1_SUCCESS) {
   706                  gnutls_assert();
   707                  result = _gnutls_asn2err(result);
   708                  goto cleanup;
   709          }
   710
   711          result =
   712              _gnutls_x509_der_encode_and_copy(c2, "", pkcs12,
   713                                               "authSafe.content", 1);
   714          if (result < 0) {
   715                  gnutls_assert();
   716                  goto cleanup;
   717          }
   718          asn1_delete_structure(&c2);
   719
   720          return 0;
   721
   722        cleanup:
   723          asn1_delete_structure(&c2);
   724          return result;
   725
   726  }
